/// <summary>
/// Controller class for sales picking list generation service
/// </summary>
class METSalesPickingListGenerationController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        SysOperationController controller = new METSalesPickingListGenerationController();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        controller.parmLoadFromSysLastValue(false); // parameters are set via code

        return controller;
    }

/// <summary>New object</summary>
protected void new()
{
    super(classstr(METSalesPickingListGenerationService), methodstr(METSalesPickingListGenerationService, process), SysOperationExecutionMode::Synchronous);
}

    /// <summary>Main method</summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        METSalesPickingListGenerationContract       dataContract;
        METSalesPickingListGenerationController     controller;
        FormRun                                     formRun;
        FormDataSource                              orderExtractScreenTmp_ds;
        MultiSelectionHelper                        helper;
        METOrderExtractScreenTmp                    orderExtractScreenTmp;
        Map                                         soMap;
        MapEnumerator                               mapEnumerator;
        container                                   ocsCodeCon, salesOrderOSCCon;
        SalesId                                     salesId;

        soMap                       = new Map(Types::String, Types::Container);
        formRun                     = _args.caller();
        orderExtractScreenTmp_ds    = formRun.dataSource(formDataSourceStr(METOrderExtractScreen, METOrderExtractScreenTmpDS));
        helper                      = MultiSelectionHelper::construct();
        helper.parmDataSource(orderExtractScreenTmp_ds);

        orderExtractScreenTmp       = helper.getfirst();

        while (orderExtractScreenTmp)
        {
            if(!soMap.exists(orderExtractScreenTmp.SalesId))
            {
                soMap.insert(orderExtractScreenTmp.SalesId, [orderExtractScreenTmp.OSCCode]);
            }
            else
            {
                ocsCodeCon          = soMap.lookup(orderExtractScreenTmp.SalesId);
                if(!conFind(ocsCodeCon, orderExtractScreenTmp.OSCCode))
                {
                    ocsCodeCon      = conIns(ocsCodeCon, conLen(ocsCodeCon) + 1, orderExtractScreenTmp.OSCCode);
                    soMap.remove(orderExtractScreenTmp.SalesId);
                    soMap.insert(orderExtractScreenTmp.SalesId, ocsCodeCon);
                }
            }
            
            orderExtractScreenTmp   = helper.getNext(); //Reading the next row
        }

        mapEnumerator               = soMap.getEnumerator();

        while (mapEnumerator.moveNext())
        {
            salesId                 = mapEnumerator.currentKey();
            ocsCodeCon              = mapEnumerator.currentValue();
            ocsCodeCon              = conIns(ocsCodeCon, 1, salesId);
            salesOrderOSCCon        = conIns(salesOrderOSCCon, conLen(salesOrderOSCCon) + 1, ocsCodeCon);
        }

        if(conLen(salesOrderOSCCon))
        {
            controller              = METSalesPickingListGenerationController::construct(_args);            
            dataContract            = controller.getDataContractObject();
            dataContract.parmSalesOrderList(salesOrderOSCCon);
            controller.parmShowDialog(false);
            controller.startOperation(); 
            Info("@MET:MetPickingListGenerationBatchCreated");
        }
        else
        {
            warning("@MET:NoSalesOrderToProcess");
        }
    }

/// <summary>
/// Description
/// </summary>
/// <returns>Generate purchase orders</returns>
public ClassDescription defaultCaption()
{
    return "@MET:MetPickingListGeneration";
}
